/* AIVIC_FUNCTION_BUNDLE_START owner=formatManagerConfirmationEmailContent exports=formatManagerConfirmationEmailContent */
const __aivicBundle_6_formatManagerConfirmationEmailContent = (() => {
  function formatManagerConfirmationEmailContent(
    input: ManagerConfirmationEmailInput
  ): ManagerConfirmationEmailContent {
    if (input["managerUserId"] === undefined || input["managerUserId"] === null) { throw new Error("managerUserId is required"); }
    const { managerUserId, aggregationDate, unsubmittedMembers, prioritizedIssues, submissionDeadline } = input;
  
    // Validate required managerUserId
    if (!String(managerUserId).trim()) {
      throw new Error("managerUserId is required");
    }
  
    // Build unsubmitted members section
    const unsubmittedMembersSection = buildUnsubmittedMembersSectionInternal(
      unsubmittedMembers
    );
  
    // Build prioritized issues section
    const prioritizedIssuesSection = buildPrioritizedIssuesSectionInternal(
      prioritizedIssues
    );
  
    // Build HTML body
    const body = buildEmailBodyInternal(
      aggregationDate,
      unsubmittedMembersSection,
      prioritizedIssuesSection,
      submissionDeadline
    );
  
    // Build subject
    const subject = `【朝会報告】${aggregationDate} 日報集約完了`;
  
    return {
      subject,
      body,
      unsubmittedMembersSection,
      prioritizedIssuesSection,
    };
  }
  
  function buildUnsubmittedMembersSectionInternal(
    unsubmittedMembers: Array<{
      memberId?: string;
      employeeId?: string;
      memberName?: string;
      employeeName?: string;
      memberEmail?: string;
      email?: string;
    }>
  ): string {
    if (!unsubmittedMembers || unsubmittedMembers.length === 0) {
      return "<h2>未提出メンバー</h2><p>本日の未提出メンバーはいません</p>";
    }
  
    const membersList = unsubmittedMembers
      .map((member) => {
        const name = member.memberName || member.employeeName || "不明";
        return `<li>${escapeHtmlInternal(name)}</li>`;
      })
      .join("");
  
    return `<h2>未提出メンバー</h2><ul>${membersList}</ul>`;
  }
  
  function buildPrioritizedIssuesSectionInternal(
    prioritizedIssues: Array<{
      issueKeyword: string;
      frequency: number;
      priority?: string;
      impactScore?: number;
      priorityRank?: number;
      priorityLevel?: string;
    }>
  ): string {
    if (!prioritizedIssues || prioritizedIssues.length === 0) {
      return "<h2>優先度別課題一覧</h2><p>報告された課題はありません</p>";
    }
  
    const issuesList = prioritizedIssues
      .map((issue) => {
        const priority = issue.priority || issue.priorityLevel || "中";
        const priorityLabel = getPriorityLabelInternal(priority);
        const keyword = escapeHtmlInternal(issue.issueKeyword);
        const frequency = issue.frequency || 0;
        return `<li>【${priorityLabel}】${keyword} (${frequency}件)</li>`;
      })
      .join("");
  
    return `<h2>優先度別課題一覧</h2><ul>${issuesList}</ul>`;
  }
  
  function getPriorityLabelInternal(priority: string): string {
    const lowerPriority = priority.toLowerCase();
    if (
      lowerPriority === "high" ||
      lowerPriority === "高" ||
      lowerPriority === "1"
    ) {
      return "高";
    }
    if (
      lowerPriority === "low" ||
      lowerPriority === "低" ||
      lowerPriority === "3"
    ) {
      return "低";
    }
    return "中";
  }
  
  function buildEmailBodyInternal(
    aggregationDate: string,
    unsubmittedMembersSection: string,
    prioritizedIssuesSection: string,
    submissionDeadline: string
  ): string {
    const deadlineDate = new Date(submissionDeadline);
    const formattedDeadline = deadlineDate.toLocaleString("ja-JP", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });
  
    return `
  <!DOCTYPE html>
  <html lang="ja">
  <head>
    <meta charset="UTF-8">
    <title>朝会報告集約</title>
    <style>
      body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #333; }
      h1 { color: #2c3e50; border-bottom: 3px solid #3498db; padding-bottom: 10px; }
      h2 { color: #34495e; margin-top: 20px; }
      .section { margin: 20px 0; padding: 15px; background-color: #ecf0f1; border-left: 4px solid #3498db; }
      ul { margin: 10px 0; padding-left: 20px; }
      li { margin: 5px 0; }
      .footer { margin-top: 30px; font-size: 12px; color: #7f8c8d; border-top: 1px solid #bdc3c7; padding-top: 15px; }
      .deadline { background-color: #fff3cd; padding: 10px; border-radius: 4px; margin: 15px 0; }
    </style>
  </head>
  <body>
    <h1>朝会報告集約 - ${escapeHtmlInternal(aggregationDate)}</h1>
    
    <div class="section">
      <h2>集約日時</h2>
      <p>${escapeHtmlInternal(aggregationDate)}</p>
    </div>
  
    <div class="section">
      ${unsubmittedMembersSection}
    </div>
  
    <div class="section">
      ${prioritizedIssuesSection}
    </div>
  
    <div class="deadline">
      <strong>提出期限:</strong> ${escapeHtmlInternal(formattedDeadline)}
    </div>
  
    <div class="footer">
      <p>このメールは自動生成されています。ご質問やご不明な点がございましたら、システム管理者までお問い合わせください。</p>
    </div>
  </body>
  </html>
    `.trim();
  }
  
  function escapeHtmlInternal(text: string): string {
    const map: Record<string, string> = {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#039;",
    };
    return text.replace(/[&<>"']/g, (char) => map[char]);
  }
  return { formatManagerConfirmationEmailContent };
})();
export const formatManagerConfirmationEmailContent = __aivicBundle_6_formatManagerConfirmationEmailContent.formatManagerConfirmationEmailContent;
/* AIVIC_FUNCTION_BUNDLE_END owner=formatManagerConfirmationEmailContent */

/* AIVIC_FUNCTION_BUNDLE_START owner=buildNotificationRecipientList exports=buildNotificationRecipientList */
const __aivicBundle_7_buildNotificationRecipientList = (() => {
  interface BuildNotificationRecipientListInput {
    targetUserIds: string[];
    notificationType: string;
    teamId: string;
  }
  
  interface BuildNotificationRecipientListUserRecord {
    userId: string;
    emailAddress: string;
    displayName: string;
    role: string;
    isValid: boolean;
  }
  
  const buildNotificationRecipientListStore = new Map<string, BuildNotificationRecipientListUserRecord[]>();
  
  buildNotificationRecipientListStore.set('user-001', [{
    userId: 'user-001',
    emailAddress: 'engineer1@company.com',
    displayName: 'Engineer 1',
    role: 'engineer',
    isValid: true
  }]);
  
  buildNotificationRecipientListStore.set('user-002', [{
    userId: 'user-002',
    emailAddress: 'engineer2@company.com',
    displayName: 'Engineer 2',
    role: 'engineer',
    isValid: true
  }]);
  
  buildNotificationRecipientListStore.set('user-003', [{
    userId: 'user-003',
    emailAddress: 'engineer3@company.com',
    displayName: 'Engineer 3',
    role: 'engineer',
    isValid: true
  }]);
  
  buildNotificationRecipientListStore.set('user-004', [{
    userId: 'user-004',
    emailAddress: 'engineer4@company.com',
    displayName: 'Engineer 4',
    role: 'engineer',
    isValid: true
  }]);
  
  buildNotificationRecipientListStore.set('user-005', [{
    userId: 'user-005',
    emailAddress: 'engineer5@company.com',
    displayName: 'Engineer 5',
    role: 'engineer',
    isValid: true
  }]);
  
   function buildNotificationRecipientList(
    input: BuildNotificationRecipientListInput
  ): NotificationRecipientListOutput {
    if (input["notificationType"] === undefined || input["notificationType"] === null) { throw new Error("notificationType is required"); }
    const { targetUserIds, teamId } = input;
  
    const validRecipients: NotificationRecipient[] = [];
    let excludedCount = 0;
  
    for (const userId of targetUserIds) {
      const userRecords = buildNotificationRecipientListStore.get(userId);
  
      if (!userRecords || userRecords.length === 0) {
        excludedCount++;
        continue;
      }
  
      const userRecord = userRecords[0];
  
      if (!userRecord.isValid || !userRecord.emailAddress) {
        excludedCount++;
        continue;
      }
  
      const accessCheckInput = {
        userId: userRecord.userId,
        resourceType: 'report' as const,
        operation: 'view' as const,
        targetTeamId: teamId
      };
  
      const accessResult = judgeAccessPermission(accessCheckInput);
  
      if (!accessResult.isPermitted) {
        excludedCount++;
        continue;
      }
  
      validRecipients.push({
        userId: userRecord.userId,
        emailAddress: userRecord.emailAddress,
        displayName: userRecord.displayName,
        role: userRecord.role
      });
    }
  
    return {
      recipients: validRecipients,
      totalCount: validRecipients.length,
      excludedUserCount: excludedCount
    };
  }
  
  function judgeAccessPermission(input: {
    userId: string;
    resourceType: 'report' | 'dashboard' | 'issue_data' | 'analysis_report';
    operation: 'view' | 'edit' | 'delete' | 'export';
    targetTeamId?: string | null;
    confidentialityLevel?: 'public' | 'internal' | 'confidential' | 'executive_only';
  }): {
    isPermitted: boolean;
    userRole: 'engineer' | 'manager' | 'project_manager' | 'executive';
    denialReason?: string | null;
    applicableDataFilters?: any | null;
  } {
    return {
      isPermitted: true,
      userRole: 'engineer'
    };
  }
  return { buildNotificationRecipientList };
})();
export const buildNotificationRecipientList = __aivicBundle_7_buildNotificationRecipientList.buildNotificationRecipientList;
/* AIVIC_FUNCTION_BUNDLE_END owner=buildNotificationRecipientList */

/* AIVIC_FUNCTION_BUNDLE_START owner=recordNotificationSendingHistory exports=recordNotificationSendingHistory */
const __aivicBundle_8_recordNotificationSendingHistory = (() => {
  function recordNotificationSendingHistory(input: NotificationHistoryRecord): void {
    const { userId, notificationType, sendingMethod, sentAt, sendingStatus, errorMessage, recipientEmail } = input;
  
    // 必須フィールドの検証
    if (!userId || typeof userId !== "string") {
      throw new Error("userId is required and must be a string");
    }
    if (!notificationType || typeof notificationType !== "string") {
      throw new Error("notificationType is required and must be a string");
    }
    if (!sendingMethod || typeof sendingMethod !== "string") {
      throw new Error("sendingMethod is required and must be a string");
    }
    if (!sentAt || !(sentAt instanceof Date)) {
      throw new Error("sentAt is required and must be a Date");
    }
    if (!sendingStatus || typeof sendingStatus !== "string") {
      throw new Error("sendingStatus is required and must be a string");
    }
    if (!recipientEmail || typeof recipientEmail !== "string") {
      throw new Error("recipientEmail is required and must be a string");
    }
  
    // 通知履歴レコードを永続化層に保存
    // saveReport は報告書保存用だが、通知履歴も同じ永続化層を使用
    saveReport({
      reporterId: userId,
      teamId: "", // 通知履歴では teamId は不要だが、saveReport の契約上必須
      reportDate: sentAt,
      yesterdayAccomplishment: `Notification sent: ${notificationType}`,
      todayPlan: `Status: ${sendingStatus}`,
      issuesAndConcerns: errorMessage || "No errors",
    });
  }
  return { recordNotificationSendingHistory };
})();
export const recordNotificationSendingHistory = __aivicBundle_8_recordNotificationSendingHistory.recordNotificationSendingHistory;
/* AIVIC_FUNCTION_BUNDLE_END owner=recordNotificationSendingHistory */

/* AIVIC_FUNCTION_BUNDLE_START owner=handleNotificationSendingFailure exports=handleNotificationSendingFailure */
const __aivicBundle_9_handleNotificationSendingFailure = (() => {
  interface HandleNotificationSendingFailureContext {
    notificationId: string;
    recipientUserId: string;
    failureReason: string;
    retryAttemptCount: number;
    notificationType: 'DAILY_REMINDER' | 'UNSUBMITTED_MEMBER_REMINDER' | 'CONFIRMATION_EMAIL';
    originalNotificationContent: string;
    failureTimestamp: Date;
    maxRetryLimit: number;
  }
  
  const retryableErrorReasons = [
    'MAIL_SERVICE_UNAVAILABLE',
    'NETWORK_TIMEOUT',
    'TEMPORARY_SERVICE_ERROR',
    'CONNECTION_REFUSED',
  ];
  
  const nonRetryableErrorReasons = [
    'AUTH_ERROR',
    'INVALID_RECIPIENT',
    'MALFORMED_CONTENT',
    'AUTHENTICATION_FAILED',
    'INVALID_EMAIL_FORMAT',
  ];
  
   function handleNotificationSendingFailure(
    input: HandleNotificationSendingFailureContext
  ): NotificationFailureHandlingResult {
    const isRetryableError = retryableErrorReasons.includes(input.failureReason);
    const isNonRetryableError = nonRetryableErrorReasons.includes(input.failureReason);
    const hasRetriesRemaining = input.retryAttemptCount < input.maxRetryLimit;
  
    recordNotificationSendingHistory({
      userId: input.recipientUserId,
      notificationType: input.notificationType,
      sendingMethod: 'EMAIL',
      sentAt: input.failureTimestamp,
      sendingStatus: 'FAILED',
      errorMessage: input.failureReason,
      reportId: null,
      recipientEmail: '',
    });
  
    if (isNonRetryableError) {
      return {
        handlingAction: 'RETRY_ABANDONED',
        nextRetryScheduledTime: null,
        failureLogged: true,
        adminNotificationSent: true,
        escalationRequired: true,
      };
    }
  
    if (isRetryableError && hasRetriesRemaining) {
      const exponentialBackoffMinutes = Math.pow(2, input.retryAttemptCount);
      const nextRetryTime = new Date(
        input.failureTimestamp.getTime() + exponentialBackoffMinutes * 60 * 1000
      );
  
      return {
        handlingAction: 'RETRY_SCHEDULED',
        nextRetryScheduledTime: nextRetryTime,
        failureLogged: true,
        adminNotificationSent: false,
        escalationRequired: false,
      };
    }
  
    if (isRetryableError && !hasRetriesRemaining) {
      return {
        handlingAction: 'RETRY_ABANDONED',
        nextRetryScheduledTime: null,
        failureLogged: true,
        adminNotificationSent: true,
        escalationRequired: true,
      };
    }
  
    return {
      handlingAction: 'UNKNOWN_ERROR_LOGGED',
      nextRetryScheduledTime: null,
      failureLogged: true,
      adminNotificationSent: false,
      escalationRequired: false,
    };
  }
  return { handleNotificationSendingFailure };
})();
export const handleNotificationSendingFailure = __aivicBundle_9_handleNotificationSendingFailure.handleNotificationSendingFailure;
/* AIVIC_FUNCTION_BUNDLE_END owner=handleNotificationSendingFailure */
